const SOLICITUDES = {"PC3-N01": {"contract_version": "1.0", "company_id": "MYS-DEMO", "request_id": "SOL-PC3-N01", "correlation_id": "COR-PC3-001", "opportunity_id": "OPP-DEMO-001", "customer_id": "CLI-DEMO-001", "quotation_id": "COT-DEMO-001", "quotation_version": 1, "acceptance_id": "ACE-PC3-001"}, "PC3-E01": {"contract_version": "1.0", "company_id": "MYS-DEMO", "request_id": "SOL-PC3-E01", "correlation_id": "COR-PC3-002", "opportunity_id": "OPP-DEMO-002", "customer_id": "CLI-DEMO-001", "quotation_id": "COT-DEMO-002", "quotation_version": 1, "acceptance_id": "ACE-PC3-002"}, "PC3-E02": {"contract_version": "1.0", "company_id": "MYS-DEMO", "request_id": "SOL-PC3-E02", "correlation_id": "COR-PC3-001", "opportunity_id": "OPP-DEMO-001", "customer_id": "CLI-DEMO-001", "quotation_id": "COT-DEMO-004", "quotation_version": 2, "acceptance_id": "ACE-PC3-003"}, "PC3-F01": {"contract_version": "1.0", "company_id": "MYS-DEMO", "request_id": "SOL-PC3-F01", "correlation_id": "COR-PC3-004", "opportunity_id": "OPP-DEMO-001", "customer_id": "CLI-DEMO-001", "quotation_id": "COT-DEMO-003", "quotation_version": 1, "acceptance_id": "ACE-PC3-004"}};
const caso = $input.first().json.caso;
if (caso === 'PC3-F01 · reanudar') {
  return [{ json: { caso, url: 'http://compuerta:8000/solicitudes/SOL-PC3-F01/reanudar', body: {} } }];
}
return [{ json: { caso, url: 'http://compuerta:8000/solicitudes', body: SOLICITUDES[caso] } }];

const r = $input.first().json;
const caso = $('Preparar solicitud').first().json.caso;
if (!r.respuesta) { return [{ json: { titulo: `${caso}: sin respuesta tipificada`, texto: JSON.stringify(r) } }]; }
const x = r.respuesta;
const rep = (r.senales_reposicion || []).map(s => `${s.signal_id} (faltan ${s.faltante} de ${s.sku})`).join(', ') || '—';
const cond = (x.conditions || []).map(c => `${c.sku}: pedido ${c.requested_quantity}, disponible ${c.available_quantity}, fecha prometida: ninguna`).join('; ') || '—';
const texto = [
  `Resultado: ${x.status} / ${x.code}`, `Motivo: ${x.message}`, `Quién actúa: ${x.responsible_role}`,
  `Siguiente paso: ${x.required_action}`, `Total: ${x.total ?? '—'} ${x.currency ?? ''}`,
  `Condiciones: ${cond}`, `order_id: ${x.order_id} (no se creó pedido)`,
  `IDs: ${x.request_id} · ${x.correlation_id} · REP: ${rep}`].join('\n');
return [{ json: { titulo: `${caso} · modo determinista (sin IA)`, texto, respuesta: x } }];
